WITH risky_traders AS (
    SELECT DISTINCT t.tradereg FROM trader t JOIN transactionrecord tr ON t.tradereg = tr.trdref WHERE ((CAST(t.trading_performance->'risklevel'->>'levratio' AS numeric) > 5.0 AND t.trading_performance->'risklevel'->>'risklevel' = 'Aggressive') OR (t.voldaily / CAST(t.acctbal AS numeric) > 0.5))
),
manipulation_flagged AS (
    SELECT DISTINCT tr.trdref as traderef FROM transactionrecord tr WHERE (tr.risk_indicators->>'layerind') = 'Confirmed' OR ((tr.risk_indicators->>'spoofprob')::numeric > 0.75 AND (tr.modfreq / (1 - tr.cancelpct)) > 1.0)
),
candidates AS (
    SELECT rt.tradereg FROM risky_traders rt JOIN manipulation_flagged mf ON rt.tradereg = mf.traderef
),
trader_updr AS (
    SELECT c.tradereg, AVG((ABS(ab.patsim - ab.peercorr)) / GREATEST(CAST(0.01 AS numeric), ab.patsim)) as trader_avg_updr
    FROM candidates c
    JOIN advancedbehavior ab ON ab.translink IN (SELECT tr2.transreg FROM transactionrecord tr2 WHERE tr2.trdref = c.tradereg)
    GROUP BY c.tradereg
)
SELECT AVG(trader_avg_updr) as final_avg FROM trader_updr;

